create table if not exists public.election_governance_risks(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,title text not null,description text not null,category text not null,likelihood integer not null check(likelihood between 1 and 5),impact integer not null check(impact between 1 and 5),risk_score integer not null check(risk_score between 1 and 25),mitigation text not null,owner_id uuid references public.admins(id) on delete set null,status text not null default 'open',review_interval_days integer not null default 30 check(review_interval_days between 1 and 365),next_review_date date not null,last_reviewed_at timestamptz,last_reviewed_by uuid references public.admins(id) on delete set null,created_by uuid references public.admins(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists election_governance_risks_monitor_idx on public.election_governance_risks(award_space_id,status,next_review_date,risk_score desc);
create table if not exists public.election_governance_risk_reviews(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,risk_id uuid not null references public.election_governance_risks(id) on delete cascade,likelihood integer not null check(likelihood between 1 and 5),impact integer not null check(impact between 1 and 5),risk_score integer not null check(risk_score between 1 and 25),note text not null,reviewed_by uuid references public.admins(id) on delete set null,reviewed_at timestamptz not null default now());
create index if not exists election_governance_risk_reviews_idx on public.election_governance_risk_reviews(award_space_id,risk_id,reviewed_at desc);
alter table public.election_governance_risks enable row level security;
alter table public.election_governance_risk_reviews enable row level security;
